    virtual CThingBuilding* GetBuilding() const = 0;                     // slot 14
    bool GetSeat();                                                      // 0x0096CB40
    CIntelligentPointer<CThing> Table;                                   // +0x14
    long SeatIndex;                                                      // +0x1c
    long SeatActionPointIndex;                                           // +0x20
    C3DVector SeatPos;                                                   // +0x24
    CRightHandedSet SeatRHSet;                                           // +0x30
