    ParentThing->PeekBaseDef().GetSubDef(&def);
    if (course >= def->Courses)
        return;
    for (unsigned long i = 0; i < Coins.size(); ++i) {
        CCharString name(Coins[i].Thing.Get()->GetScriptName());
        if (name == "" || name == "NULL")
